 route('POST','/v1/intents/:id/notify','Avisar cuando haya liquidez',empty,async r=>db.tx(async q=>{requireValue(await q.one('SELECT id FROM intents WHERE id=$1 AND user_id=$2',[param(r),uid(r)]));await q.exec('UPDATE intents SET notify_liquidity=true WHERE id=$1',[param(r)]);await q.exec('UPDATE preferences SET data=jsonb_set(data,\'{liquidity}\',\'true\') WHERE user_id=$1',[uid(r)]);return {ok:true};}));
 route('GET','/v1/radar','Radar agregado k>=3, sin identidades o coordenadas',empty,async r=>{await limited(db,'radar:'+uid(r),35,60000);return matching.radar(uid(r));});
