 route('POST','/v1/matches/:id/respond','VOY/PASO con idempotencia y TTL',z.object({response:z.enum(['accepted','passed'])}),async(r,b)=>matching.respond(uid(r),param(r),b.response,key(r)));
 route('POST','/v1/matches/:id/check-in','Check-in manual o proximidad en primer plano',z.object({location:z.object({lat:z.number().min(-85).max(85),lon:z.number().min(-180).max(180)}).optional()}),async(r,b)=>matching.checkIn(uid(r),param(r),b.location,key(r)));
 route('POST','/v1/matches/:id/leave','Salida de seguridad sin penalización',empty,async r=>db.tx(async q=>{await matching.safeExit(q,uid(r),param(r));return {ok:true};}));
 route('POST','/v1/matches/:id/venue','Cambiar a punto alternativo validado por seguridad',empty,async r=>db.tx(async q=>{const view=await matching.view(q,uid(r),param(r));if(view.state!=='CONFIRMED')throw new ApiError('MATCH_NOT_CONFIRMED','El grupo aún no está confirmado.',409);const m=requireValue(await q.one<Match>('SELECT * FROM matches WHERE id=$1',[param(r)]));const next=m.fallback_venues[0];if(!next)throw new ApiError('NO_FALLBACK','No hay otro lugar validado. Puedes abandonar sin penalización.',409);const v=await q.one<VenueRow>('SELECT * FROM venues WHERE id=$1 AND safe=true AND public=true',[next]);requireValue(v);await q.exec('UPDATE matches SET venue_id=$1,fallback_venues=$2::jsonb WHERE id=$3',[next,JSON.stringify(m.fallback_venues.slice(1)),m.id]);for(const mm of await q.all<Member>('SELECT * FROM match_members WHERE match_id=$1 AND safety_exit=false',[m.id]))await q.exec('INSERT INTO notifications(id,user_id,kind,title,body,created_at,expires_at) VALUES($1,$2,$3,$4,$5,$6,$7)',[id(),mm.user_id,'safety','Cambio de punto de encuentro','Consulta el nuevo lugar antes de salir.',Date.now(),Date.now()+86400000]);await audit(q,uid(r),'match.venue_changed',m.id);return matching.view(q,uid(r),m.id);}));
 route('POST','/v1/matches/:id/feedback','Feedback privado, sin puntuación pública',z.object({groupAppeared:z.boolean(),feltSafe:z.boolean(),again:z.boolean()}),async(r,b)=>db.tx(async q=>{const m=await matching.view(q,uid(r),param(r));if(m.state!=='COMPLETED')throw new ApiError('MATCH_NOT_COMPLETED','El encuentro aún no ha terminado.',409);await q.exec('UPDATE match_members SET feedback=$1::jsonb WHERE match_id=$2 AND user_id=$3',[JSON.stringify(b),param(r),uid(r)]);return {ok:true};}));
 route('POST','/v1/demo/matches/:id/complete','Simular fin y asistencia de actores demo',empty,async r=>{if(!env.demo)throw new ApiError('NOT_FOUND','No disponible.',404);return db.tx(async q=>{const view=await matching.view(q,uid(r),param(r));if(!view.isDemo||view.state!=='CONFIRMED')throw new ApiError('DEMO_ONLY','Sólo para encuentros demo confirmados.',409);await q.exec('UPDATE match_members SET checked_in=true WHERE match_id=$1 AND user_id IN(SELECT id FROM users WHERE is_demo_actor=true)',[param(r)]);await matching.complete(q,param(r));return matching.view(q,uid(r),param(r));});});
 route('GET','/v1/matches/:id/messages','Chat contextual con ventana temporal',empty,async r=>db.tx(async q=>{const m=await matching.view(q,uid(r),param(r));if(!m.chatOpen)throw new ApiError('CHAT_CLOSED','El chat está disponible desde antes del NOW hasta 30 días después, si asististe.',403);const now=Date.now();await q.exec('UPDATE messages SET delivered_at=COALESCE(delivered_at,$1) WHERE match_id=$2 AND sender_id<>$3 AND state=\'visible\' AND expires_at>$1',[now,param(r),uid(r)]);const rows=await q.all<{id:string;sender_id:string;display_name:string;body:string;created_at:number;delivered_at:number|null;read_at:number|null}>('SELECT x.id,x.sender_id,u.display_name,x.body,x.created_at,x.delivered_at,x.read_at FROM messages x JOIN users u ON u.id=x.sender_id WHERE match_id=$1 AND x.state=$2 AND expires_at>$3 AND NOT EXISTS(SELECT 1 FROM blocks b WHERE (b.blocker=$4 AND b.blocked=x.sender_id) OR (b.blocked=$4 AND b.blocker=x.sender_id)) ORDER BY created_at LIMIT 100',[param(r),'visible',now,uid(r)]);return rows.map(x=>({id:x.id,senderId:x.sender_id,displayName:x.display_name,body:x.body,createdAt:iso(x.created_at),delivery:x.read_at?'read':x.delivered_at?'received':'sent'})) satisfies MessageView[];}));
 route('POST','/v1/matches/:id/messages/read','Marcar mensajes visibles como leídos',empty,async r=>db.tx(async q=>{const m=await matching.view(q,uid(r),param(r));if(!m.chatOpen)throw new ApiError('CHAT_CLOSED','El chat no está disponible.',403);const now=Date.now();await q.exec('UPDATE messages SET delivered_at=COALESCE(delivered_at,$1),read_at=COALESCE(read_at,$1) WHERE match_id=$2 AND sender_id<>$3 AND state=\'visible\' AND expires_at>$1',[now,param(r),uid(r)]);return {ok:true};}));
 route('POST','/v1/matches/:id/typing','Publicar estado efímero de escritura',z.object({typing:z.boolean()}),async(r,b)=>db.tx(async q=>{const m=await matching.view(q,uid(r),param(r));if(!m.chatOpen)throw new ApiError('CHAT_CLOSED','El chat no está disponible.',403);if(b.typing)await q.exec('INSERT INTO chat_typing(match_id,user_id,updated_at) VALUES($1,$2,$3) ON CONFLICT(match_id,user_id) DO UPDATE SET updated_at=$3',[param(r),uid(r),Date.now()]);else await q.exec('DELETE FROM chat_typing WHERE match_id=$1 AND user_id=$2',[param(r),uid(r)]);return {ok:true};}));
 route('GET','/v1/matches/:id/typing','Consultar indicador efímero de escritura',empty,async r=>db.tx(async q=>{const m=await matching.view(q,uid(r),param(r));if(!m.chatOpen)throw new ApiError('CHAT_CLOSED','El chat no está disponible.',403);return q.all('SELECT u.id,u.display_name AS "displayName" FROM chat_typing t JOIN users u ON u.id=t.user_id JOIN match_members mm ON mm.match_id=t.match_id AND mm.user_id=t.user_id AND mm.safety_exit=false WHERE t.match_id=$1 AND t.user_id<>$2 AND t.updated_at>$3 AND NOT EXISTS(SELECT 1 FROM blocks b WHERE (b.blocker=$2 AND b.blocked=t.user_id) OR (b.blocked=$2 AND b.blocker=t.user_id))',[param(r),uid(r),Date.now()-5000]);}));
 route('POST','/v1/matches/:id/messages','Enviar texto sin archivos, enlaces o PII',z.object({body:z.string().trim().min(1).max(500)}),async(r,b)=>{await limited(db,'chat:'+uid(r),10,60000);return db.tx(async q=>{await active(q,uid(r));const m=await matching.view(q,uid(r),param(r));if(!m.chatOpen)throw new ApiError('CHAT_CLOSED','El chat no está disponible.',403);if(!textAllowed(b.body))throw new ApiError('CONTENT_FILTER','Evita enlaces, datos de contacto o contenido inapropiado.',422);const mid=id();await q.exec('INSERT INTO messages(id,match_id,sender_id,body,created_at,expires_at) VALUES($1,$2,$3,$4,$5,$6)',[mid,param(r),uid(r),b.body,Date.now(),new Date(m.endsAt).getTime()+config.chatRetentionDays*86400000]);return {id:mid};});});
 route('POST','/v1/reports','Reportar persona o mensaje con contexto',reportInput,async(r,b)=>{await limited(db,'report:'+uid(r),5,3600000);return safety.report(uid(r),b,key(r));});
