 route('GET','/v1/blocks','Bloqueos propios',empty,async r=>db.tx(q=>q.all('SELECT b.blocked AS id,u.display_name AS "displayName" FROM blocks b JOIN users u ON u.id=b.blocked WHERE b.blocker=$1',[uid(r)])));
 route('DELETE','/v1/blocks/:id','Revocar bloqueo propio',empty,async r=>db.tx(async q=>{await q.exec('DELETE FROM blocks WHERE blocker=$1 AND blocked=$2',[uid(r),param(r)]);return {ok:true};}));
 route('GET','/v1/notifications','Notificaciones propias',empty,async r=>db.tx(async q=>(await q.all<{id:string;kind:string;title:string;body:string;read:boolean;created_at:number}>('SELECT id,kind,title,body,read,created_at FROM notifications WHERE user_id=$1 ORDER BY created_at DESC LIMIT 50',[uid(r)])).map(n=>({...n,createdAt:iso(n.created_at)}))));
 route('GET','/v1/me/attendance-reviews','Preguntas de asistencia asignadas tras un NOW',empty,async r=>db.tx(async q=>{const rows=await q.all<{match_id:string;subject_id:string;display_name:string;activity_id:string;label:string;emoji:string;scheduled_at:number;required_yes:number;yes_votes:number}>('SELECT a.match_id,a.subject_id,u.display_name,m.activity AS activity_id,act.label,act.emoji,m.scheduled_at,v.required_yes,v.yes_votes FROM attendance_review_assignments a JOIN attendance_verifications v ON v.match_id=a.match_id AND v.subject_id=a.subject_id AND v.state=\'pending\' JOIN matches m ON m.id=a.match_id AND m.state=\'COMPLETED\' JOIN match_members me ON me.match_id=m.id AND me.user_id=a.reviewer_id AND me.checked_in=true AND me.safety_exit=false JOIN match_members target ON target.match_id=m.id AND target.user_id=a.subject_id AND target.checked_in=true AND target.safety_exit=false JOIN users u ON u.id=target.user_id JOIN activities act ON act.id=m.activity WHERE a.reviewer_id=$1 AND a.state=\'pending\' AND m.ends_at>$2 AND NOT EXISTS(SELECT 1 FROM blocks b WHERE (b.blocker=$1 AND b.blocked=a.subject_id) OR (b.blocked=$1 AND b.blocker=a.subject_id)) ORDER BY m.ends_at,a.subject_id',[uid(r),Date.now()-7*86400000]);return rows.map(x=>({id:x.match_id+'-'+x.subject_id,matchId:x.match_id,subjectId:x.subject_id,displayName:x.display_name,activity:{id:x.activity_id,label:x.label,emoji:x.emoji},scheduledAt:iso(x.scheduled_at),otherReviewersNeeded:Math.max(0,x.required_yes-x.yes_votes)}));}));
 route('POST','/v1/matches/:matchId/attendance-reviews/:subjectId','Confirmar únicamente si otra persona asistió',z.object({attended:z.boolean()}),async(r,b)=>db.tx(async q=>{const matchId=param(r,'matchId'),subjectId=param(r,'subjectId'),reviewer=uid(r);await active(q,reviewer);if(subjectId===reviewer)throw new ApiError('REVIEW_INVALID','No puedes confirmar tu propia asistencia.',403);const match=await q.one('SELECT id FROM matches WHERE id=$1 AND state=\'COMPLETED\' AND ends_at>$2',[matchId,Date.now()-7*86400000]);if(!match)throw new ApiError('REVIEW_EXPIRED','Esta confirmación ya no está disponible.',404);const assignment=await q.one('SELECT state FROM attendance_review_assignments WHERE match_id=$1 AND reviewer_id=$2 AND subject_id=$3',[matchId,reviewer,subjectId]);if(!assignment||assignment.state!=='pending'||!await q.one('SELECT 1 FROM match_members WHERE match_id=$1 AND user_id=$2 AND checked_in=true AND safety_exit=false',[matchId,reviewer]))throw new ApiError('REVIEW_UNAVAILABLE','Esta pregunta no está disponible.',404);const verify=await q.one<{state:string;required_yes:number;yes_votes:number}>('SELECT state,required_yes,yes_votes FROM attendance_verifications WHERE match_id=$1 AND subject_id=$2',[matchId,subjectId]);if(!verify||verify.state!=='pending')throw new ApiError('REVIEW_CLOSED','La confirmación ya se ha cerrado.',409);const now=Date.now();await q.exec('UPDATE attendance_review_assignments SET state=$1,responded_at=$2 WHERE match_id=$3 AND reviewer_id=$4 AND subject_id=$5',[b.attended?'yes':'no',now,matchId,reviewer,subjectId]);const nextYes=verify.yes_votes+(b.attended?1:0),nextState=b.attended&&nextYes>=verify.required_yes?'verified':b.attended?'pending':'rejected';await q.exec('UPDATE attendance_verifications SET state=$1,yes_votes=$2,no_votes=no_votes+$3,decided_at=CASE WHEN $1<>\'pending\' THEN $4 ELSE decided_at END WHERE match_id=$5 AND subject_id=$6',[nextState,nextYes,b.attended?0:1,now,matchId,subjectId]);if(nextState!=='pending')await q.exec('UPDATE attendance_review_assignments SET state=\'cancelled\' WHERE match_id=$1 AND subject_id=$2 AND state=\'pending\'',[matchId,subjectId]);return {ok:true,verification:nextState};}));
 route('POST','/v1/notifications/read','Marcar como leídas',empty,async r=>db.tx(async q=>{await q.exec('UPDATE notifications SET read=true WHERE user_id=$1',[uid(r)]);return {ok:true};}));
 route('POST','/v1/devices','Registrar token push del dispositivo',z.object({platform:z.enum(['ios','android']),pushToken:z.string().regex(/^(ExponentPushToken|ExpoPushToken)\[[\w-]+\]$/)}),async(r,b)=>db.tx(async q=>{await q.exec('INSERT INTO devices VALUES($1,$2,$3,$4,$5) ON CONFLICT(push_token) DO UPDATE SET user_id=$2,platform=$3',[id(),uid(r),b.platform,b.pushToken,Date.now()]);return {ok:true};}));
 route('GET','/v1/privacy/export','Exportar datos personales propios en JSON',empty,async(r,_b,p)=>{p.header('Content-Disposition','attachment; filename="now-mis-datos.json"');return safety.export(uid(r));});
 route('DELETE','/v1/account','Borrar cuenta, sesiones y localización',empty,async(r,_b,p)=>{const result=await safety.deleteAccount(uid(r));p.clearCookie('now_access',{path:'/'}).clearCookie('now_refresh',{path:'/'});return result;});
 route('GET','/v1/moderation/mine','Decisiones y apelaciones propias',empty,async r=>db.tx(async q=>({cases:await q.all('SELECT id,action,rationale,created_at,expires_at FROM moderation_cases WHERE subject=$1 ORDER BY created_at DESC',[uid(r)]),appeals:await q.all('SELECT id,case_id,state,decision,created_at FROM appeals WHERE user_id=$1',[uid(r)])})));
 route('POST','/v1/appeals','Apelar una decisión propia',z.object({caseId:uuid,reason:z.string().trim().min(10).max(2000)}),async(r,b)=>db.tx(async q=>{requireValue(await q.one('SELECT id FROM moderation_cases WHERE id=$1 AND subject=$2',[b.caseId,uid(r)]));if(await q.one('SELECT id FROM appeals WHERE case_id=$1 AND user_id=$2 AND state=$3',[b.caseId,uid(r),'open']))throw new ApiError('APPEAL_EXISTS','Ya existe una apelación abierta.',409);await q.exec('INSERT INTO appeals(id,user_id,case_id,reason,created_at) VALUES($1,$2,$3,$4,$5)',[id(),uid(r),b.caseId,b.reason,Date.now()]);return {ok:true};}));
 const staff={roles:['admin','moderator']};const admin={roles:['admin']};
 route('GET','/v1/admin/metrics','Métricas operativas agregadas',empty,async()=>db.tx(async q=>{const count=async(sql:string)=>(await q.one<{n:string}>(sql))?.n||'0';const users=Number(await count("SELECT count(*) n FROM users WHERE status='active'")),intents=Number(await count('SELECT count(*) n FROM intents')),proposals=Number(await count('SELECT count(*) n FROM matches')),confirmed=Number(await count("SELECT count(*) n FROM matches WHERE state IN ('CONFIRMED','COMPLETED')")),accepted=Number(await count("SELECT count(*) n FROM match_members WHERE response='accepted' AND safety_exit=false")),attended=Number(await count('SELECT count(*) n FROM match_members WHERE checked_in=true AND safety_exit=false'));return {users,intents,proposals,confirmed,matchRate:proposals?confirmed/proposals:0,showUpRate:accepted?attended/accepted:0,reports:Number(await count("SELECT count(*) n FROM reports WHERE state IN ('open','under_review')")),irlHours:Number((await q.one<{n:number}>('SELECT COALESCE(sum(value),0) n FROM analytics_events WHERE name=$1',['irl_hours']))?.n||0),demo:env.demo,series:await q.all('SELECT name,activity,community_id,city,CAST(to_timestamp(created_at/1000)::date AS text) AS day,sum(value) AS value FROM analytics_events GROUP BY name,activity,community_id,city,day ORDER BY day DESC LIMIT 100')};}),staff);
 route('GET','/v1/admin/avatars','Fotos de perfil pendientes de revisión',empty,async()=>db.tx(q=>q.all('SELECT id,display_name,avatar_pending,avatar_pending_at FROM users WHERE avatar_pending IS NOT NULL AND status=$1 ORDER BY avatar_pending_at LIMIT 100',['active'])),staff);
 route('PATCH','/v1/admin/avatars/:id','Aprobar o rechazar foto de perfil',z.object({approved:z.boolean(),rationale:z.string().trim().min(10).max(500)}),async(r,b)=>db.tx(async q=>{const person=requireValue(await q.one<User>('SELECT * FROM users WHERE id=$1 AND avatar_pending IS NOT NULL AND status=$2',[param(r),'active']));await q.exec('UPDATE users SET avatar=CASE WHEN $1 THEN avatar_pending ELSE avatar END,avatar_pending=NULL,avatar_pending_at=NULL,updated_at=$2 WHERE id=$3',[b.approved,Date.now(),person.id]);await audit(q,uid(r),b.approved?'avatar.approved':'avatar.rejected',person.id,{rationale:b.rationale});await notify(q,person.id,'profile',b.approved?'Foto de perfil aprobada':'Foto de perfil no aprobada',b.approved?'Tu nueva foto ya se muestra a las personas con las que coincidas.':'Puedes elegir otra foto desde tu perfil.');return {ok:true};}),staff);
 route('GET','/v1/admin/users','Buscar usuarios (rol autorizado, sin PII de contacto)',empty,async r=>{const search=z.string().max(100).parse((r.query as {q?:string}).q||'');return db.tx(q=>q.all('SELECT id,username,display_name,status,role,age_status,created_at FROM users WHERE display_name ILIKE $1 OR username ILIKE $1 ORDER BY created_at DESC LIMIT 100',['%'+search+'%']));},staff);
 route('PATCH','/v1/admin/users/:id','Suspender, banear o restaurar cuenta con motivo',z.object({status:z.enum(['active','suspended','banned']),rationale:z.string().trim().min(10).max(1000)}),async(r,b)=>db.tx(async q=>{const target=requireValue(await q.one<User>('SELECT * FROM users WHERE id=$1',[param(r)]));if(target.role==='admin'||target.id===uid(r)||target.status==='deleted')throw new ApiError('FORBIDDEN','Esta cuenta no puede modificarse aquí.',403);await q.exec('UPDATE users SET status=$1 WHERE id=$2',[b.status,target.id]);if(b.status!=='active'){const ms=await q.all<{id:string}>('SELECT m.id FROM matches m JOIN match_members mm ON mm.match_id=m.id WHERE mm.user_id=$1 AND mm.safety_exit=false AND m.state IN (\'PROPOSAL_PENDING\',\'PARTIALLY_ACCEPTED\',\'CONFIRMED\')',[target.id]);for(const m of ms)await matching.safeExit(q,target.id,m.id);await q.exec('UPDATE intents SET status=$1,lat=NULL,lon=NULL,cell_x=NULL,cell_y=NULL WHERE user_id=$2',['CANCELLED',target.id]);}await q.exec('INSERT INTO moderation_cases(id,subject,actor,action,rationale,created_at) VALUES($1,$2,$3,$4,$5,$6)',[id(),target.id,uid(r),b.status,b.rationale,Date.now()]);await audit(q,uid(r),'moderation.'+b.status,target.id);return {ok:true};}),staff);
 route('GET','/v1/admin/reports','Cola de reportes priorizada',empty,async()=>db.tx(q=>q.all('SELECT * FROM reports ORDER BY severity,created_at DESC LIMIT 100')),staff);
 route('PATCH','/v1/admin/reports/:id','Revisar/resolver reporte y registrar motivo',z.object({state:z.enum(['under_review','resolved']),rationale:z.string().trim().min(10).max(1000)}),async(r,b)=>db.tx(async q=>{const report=requireValue(await q.one<{subject:string}>('SELECT subject FROM reports WHERE id=$1',[param(r)]));await q.exec('UPDATE reports SET state=$1,resolved_at=$2 WHERE id=$3',[b.state,b.state==='resolved'?Date.now():null,param(r)]);await q.exec('INSERT INTO moderation_cases(id,report_id,subject,actor,action,rationale,created_at) VALUES($1,$2,$3,$4,$5,$6,$7)',[id(),param(r),report.subject,uid(r),b.state,b.rationale,Date.now()]);await audit(q,uid(r),'report.'+b.state,param(r));return {ok:true};}),staff);
 route('GET','/v1/admin/appeals','Cola de apelaciones',empty,async()=>db.tx(q=>q.all('SELECT * FROM appeals ORDER BY created_at DESC LIMIT 100')),staff);
 route('PATCH','/v1/admin/appeals/:id','Resolver apelación',z.object({decision:z.string().min(10).max(1000)}),async(r,b)=>db.tx(async q=>{requireValue(await q.one('SELECT id FROM appeals WHERE id=$1',[param(r)]));await q.exec('UPDATE appeals SET state=$1,decision=$2 WHERE id=$3',['resolved',b.decision,param(r)]);await audit(q,uid(r),'appeal.resolved',param(r));return {ok:true};}),staff);
 route('GET','/v1/admin/communities','Gestionar comunidades',empty,async()=>db.tx(q=>q.all('SELECT id,name,kind,city,description,method,domain,enabled FROM communities ORDER BY name')),admin);
 route('POST','/v1/admin/communities','Crear comunidad',z.object({name:z.string().min(3).max(100),kind:z.string().min(3).max(30),city:z.string().min(2).max(60),description:z.string().max(300),method:z.enum(['code','domain','approval']),code:z.string().min(6).optional(),domain:z.string().min(3).optional()}),async(r,b)=>db.tx(async q=>{if((b.method==='code'&&!b.code)||(b.method==='domain'&&!b.domain))throw new ApiError('VERIFICATION_CONFIG','Configura código o dominio.');const cid=id();await q.exec('INSERT INTO communities(id,name,kind,city,description,method,code_hash,domain) VALUES($1,$2,$3,$4,$5,$6,$7,$8)',[cid,b.name,b.kind,b.city,b.description,b.method,b.code?hash(b.code):null,b.domain||null]);await audit(q,uid(r),'community.created',cid);return {id:cid};}),admin);
 route('PATCH','/v1/admin/communities/:id','Editar comunidad',z.object({name:z.string().min(3).max(100),description:z.string().max(300),enabled:z.boolean()}),async(r,b)=>db.tx(async q=>{await q.exec('UPDATE communities SET name=$1,description=$2,enabled=$3 WHERE id=$4',[b.name,b.description,b.enabled,param(r)]);await audit(q,uid(r),'community.updated',param(r));return {ok:true};}),admin);
 route('GET','/v1/admin/memberships','Solicitudes de verificación',empty,async()=>db.tx(q=>q.all('SELECT m.*,u.display_name,c.name FROM memberships m JOIN users u ON u.id=m.user_id JOIN communities c ON c.id=m.community_id WHERE m.verified=false')),admin);
 route('POST','/v1/admin/memberships','Verificar pertenencia',z.object({userId:uuid,communityId:uuid,verified:z.boolean()}),async(r,b)=>db.tx(async q=>{await q.exec('UPDATE memberships SET verified=$1 WHERE user_id=$2 AND community_id=$3',[b.verified,b.userId,b.communityId]);await audit(q,uid(r),'membership.verified',b.userId);return {ok:true};}),admin);
 route('GET','/v1/admin/activities','Taxonomía completa',empty,async()=>db.tx(q=>q.all('SELECT * FROM activities ORDER BY id')),admin);
 route('PUT','/v1/admin/activities/:activity','Configurar actividad y compatibilidad explícita',z.object({label:z.string().min(2).max(50),emoji:z.string().max(12),family:z.string().max(30),compatible:z.array(z.string().max(40)).max(30),options:z.array(z.object({id:z.string().regex(/^[a-z_]{2,30}$/),label:z.string().min(2).max(50),emoji:z.string().max(12)})).min(1).max(12),enabled:z.boolean(),minMinutes:z.number().int().min(20).max(120)}),async(r,b)=>db.tx(async q=>{const aid=z.string().regex(/^[a-z_]{2,30}$/).parse((r.params as {activity:string}).activity);await q.exec('INSERT INTO activities(id,label,emoji,family,compatible,options,enabled,min_minutes) VALUES($1,$2,$3,$4,$5::jsonb,$6::jsonb,$7,$8) ON CONFLICT(id) DO UPDATE SET label=$2,emoji=$3,family=$4,compatible=$5::jsonb,options=$6::jsonb,enabled=$7,min_minutes=$8',[aid,b.label,b.emoji,b.family,JSON.stringify(b.compatible),JSON.stringify(b.options),b.enabled,b.minMinutes]);await audit(q,uid(r),'activity.updated',null,{activity:aid});return {ok:true};}),admin);
 route('GET','/v1/admin/venues','Catálogo de lugares',empty,async()=>db.tx(q=>q.all('SELECT * FROM venues ORDER BY name')),admin);
 const venueSchema=z.object({name:z.string().min(3).max(100),address:z.string().min(5).max(200),lat:z.number().min(-85).max(85),lon:z.number().min(-180).max(180),category:z.string().max(50),activities:z.array(z.string()).min(1).max(20),safe:z.boolean(),public:z.literal(true),accessible:z.boolean(),capacity:z.number().int().min(3).max(1000),budget:z.number().int().min(0).max(3),rating:z.number().min(0).max(5),openHour:z.number().int().min(0).max(23),closeHour:z.number().int().min(0).max(23)});
 route('POST','/v1/admin/venues','Crear lugar público revisado',venueSchema,async(r,b)=>db.tx(async q=>{const vid=id();await q.exec('INSERT INTO venues(id,name,address,lat,lon,category,activities,safe,public,accessible,capacity,budget,rating,open_hour,close_hour,is_demo) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb,$8,true,$9,$10,$11,$12,$13,$14,$15)',[vid,b.name,b.address,b.lat,b.lon,b.category,JSON.stringify(b.activities),b.safe,b.accessible,b.capacity,b.budget,b.rating,b.openHour,b.closeHour,env.demo]);await audit(q,uid(r),'venue.created',vid);return {id:vid};}),admin);
 route('PATCH','/v1/admin/venues/:id','Habilitar o excluir lugar por seguridad',z.object({safe:z.boolean(),name:z.string().min(3).max(100)}),async(r,b)=>db.tx(async q=>{await q.exec('UPDATE venues SET safe=$1,name=$2 WHERE id=$3',[b.safe,b.name,param(r)]);await audit(q,uid(r),'venue.updated',param(r));return {ok:true};}),admin);
 route('GET','/v1/admin/flags','Feature flags',empty,async()=>db.tx(q=>q.all('SELECT * FROM feature_flags ORDER BY key')),admin);
 route('PATCH','/v1/admin/flags/:key','Activar/desactivar función',z.object({enabled:z.boolean()}),async(r,b)=>db.tx(async q=>{const k=z.string().max(50).parse((r.params as {key:string}).key);requireValue(await q.one('SELECT key FROM feature_flags WHERE key=$1',[k]));await q.exec('UPDATE feature_flags SET enabled=$1 WHERE key=$2',[b.enabled,k]);await audit(q,uid(r),'flag.updated',null,{key:k,enabled:b.enabled});return {ok:true};}),admin);
